import React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  interpolateColors,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const FONT_STACK =
  '"PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif';

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

export const Main: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height, fps, durationInFrames } = useVideoConfig();

  const layoutScale = Math.min(width / 1920, height / 1080);

  /* ---------------- 卡片入场（淡入 + 上移） ---------------- */
  const leftIn = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 110, mass: 0.85 },
  });
  const rightIn = spring({
    frame: Math.max(0, frame - 6),
    fps,
    config: { damping: 14, stiffness: 110, mass: 0.85 },
  });

  /* ---------------- 蓝紫连线生长 ---------------- */
  const lineGrow = interpolate(frame, [34, 82], [0, 1], {
    ...CLAMP,
    easing: Easing.inOut(Easing.cubic),
  });

  /* ---------------- 光点从左向右循环流动 ---------------- */
  const flowStart = 84;
  const flowPeriod = 72;
  const flowing = frame >= flowStart;
  const phase = flowing ? (frame - flowStart) % flowPeriod : 0;
  const dotT = phase / flowPeriod;
  const dotLeft = interpolate(dotT, [0, 1], [472, 712], CLAMP);
  const dotColor = interpolateColors(dotT, [0, 1], ["#3B82F6", "#A855F7"]);
  const dotOpacity =
    interpolate(dotT, [0, 0.12, 0.85, 1], [0, 1, 1, 0], CLAMP) * lineGrow;

  /* ---------------- 打字机效果 ---------------- */
  const fullText = "把想法写成提示词";
  const charCount = Math.floor(
    interpolate(frame, [95, 170], [0, fullText.length], CLAMP)
  );
  const typedText = fullText.slice(0, charCount);
  const cursorOpacity =
    frame >= 90 && frame <= 205
      ? Math.floor(frame / 8) % 2 === 0
        ? 1
        : 0.15
      : 0;

  /* ---------------- 右侧插画卡片缩放浮现 ---------------- */
  const illoIn = spring({
    frame: Math.max(0, frame - 172),
    fps,
    config: { damping: 12, stiffness: 105, mass: 0.75 },
  });

  /* ---------------- 画面整体后移（缩小） ---------------- */
  const shrinkEnd = Math.max(241, durationInFrames - 20);
  const sceneScale = interpolate(frame, [240, shrinkEnd], [1, 0.9], {
    ...CLAMP,
    easing: Easing.inOut(Easing.cubic),
  });

  /* ---------------- 底部标题淡入 ---------------- */
  const titleOpacity = interpolate(frame, [262, 320], [0, 1], CLAMP);
  const titleY = interpolate(frame, [262, 320], [26, 0], {
    ...CLAMP,
    easing: Easing.out(Easing.cubic),
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#05070F",
        fontFamily: FONT_STACK,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* 背景光晕 */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background:
            "radial-gradient(circle at 50% 42%, #1B2450 0%, #05070F 64%)",
        }}
      />

      <div
        style={{
          position: "relative",
          width: 1200,
          height: 600,
          transform: `scale(${layoutScale * sceneScale})`,
        }}
      >
        {/* ---------- 连线（发光 + 生长 + 光点） ---------- */}
        <div
          style={{
            position: "absolute",
            left: 480,
            top: 294,
            width: 240,
            height: 12,
            borderRadius: 12,
            background: "linear-gradient(90deg, #2E7BFF 0%, #7B5BFF 50%, #A855F7 100%)",
            filter: "blur(10px)",
            opacity: lineGrow * 0.9,
            transformOrigin: "0% 50%",
            transform: `scaleX(${lineGrow})`,
          }}
        />

        <div
          style={{
            position: "absolute",
            left: 480,
            top: 296,
            width: 240,
            height: 8,
            borderRadius: 8,
            background: "linear-gradient(90deg, #2E7BFF 0%, #7B5BFF 50%, #A855F7 100%)",
            boxShadow: "0 0 18px #4E6BFF, 0 0 40px #7B4BFF",
            transformOrigin: "0% 50%",
            transform: `scaleX(${lineGrow})`,
          }}
        />

        <div
          style={{
            position: "absolute",
            left: dotLeft,
            top: 292,
            width: 16,
            height: 16,
            borderRadius: "50%",
            background: dotColor,
            boxShadow: `0 0 16px ${dotColor}, 0 0 36px ${dotColor}`,
            opacity: dotOpacity,
          }}
        />

        {/* ---------- 左侧卡片：文本生成 ---------- */}
        <div
          style={{
            position: "absolute",
            left: 60,
            top: 160,
            width: 420,
            height: 280,
            boxSizing: "border-box",
            padding: 34,
            borderRadius: 28,
            background: "linear-gradient(158deg, #191E36 0%, #0E1120 100%)",
            border: "1px solid #2B3358",
            boxShadow: "0 26px 70px #00000080",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            opacity: leftIn,
            transform: `translateY(${(1 - leftIn) * 44}px)`,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 12,
              marginBottom: 22,
            }}
          >
            <div
              style={{
                width: 10,
                height: 10,
                borderRadius: "50%",
                background: "#3B82F6",
                boxShadow: "0 0 14px #3B82F6",
              }}
            />
            <span
              style={{
                color: "#8FB4FF",
                fontSize: 20,
                letterSpacing: 3,
                fontWeight: 500,
              }}
            >
              文本生成
            </span>
          </div>

          <div style={{ display: "flex", alignItems: "center", minHeight: 60 }}>
            <span
              style={{
                color: "#F2F5FF",
                fontSize: 40,
                fontWeight: 600,
                letterSpacing: 1,
                whiteSpace: "pre",
              }}
            >
              {typedText}
            </span>
            <div
              style={{
                width: 3,
                height: 36,
                marginLeft: 5,
                borderRadius: 2,
                background: "#8B5CF6",
                opacity: cursorOpacity,
              }}
            />
          </div>
        </div>

        {/* ---------- 右侧卡片：图像生成 ---------- */}
        <div
          style={{
            position: "absolute",
            left: 720,
            top: 160,
            width: 420,
            height: 280,
            boxSizing: "border-box",
            padding: 34,
            borderRadius: 28,
            background: "linear-gradient(158deg, #1B1A38 0%, #0F0E20 100%)",
            border: "1px solid #393060",
            boxShadow: "0 26px 70px #00000080",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            opacity: rightIn,
            transform: `translateY(${(1 - rightIn) * 44}px)`,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 12,
              marginBottom: 22,
            }}
          >
            <div
              style={{
                width: 10,
                height: 10,
                borderRadius: "50%",
                background: "#A855F7",
                boxShadow: "0 0 14px #A855F7",
              }}
            />
            <span
              style={{
                color: "#C99BFF",
                fontSize: 20,
                letterSpacing: 3,
                fontWeight: 500,
              }}
            >
              图像生成
            </span>
          </div>

          {/* 插画卡片 */}
          <div
            style={{
              width: "100%",
              height: 150,
              borderRadius: 18,
              background: "linear-gradient(150deg, #1E5BFF 0%, #6D5CFF 55%, #A855F7 100%)",
              position: "relative",
              overflow: "hidden",
              boxShadow: "0 12px 34px #1E5BFF55",
              opacity: illoIn,
              transform: `scale(${0.7 + illoIn * 0.3})`,
              transformOrigin: "50% 50%",
            }}
          >
            <div
              style={{
                position: "absolute",
                right: 30,
                top: 22,
                width: 34,
                height: 34,
                borderRadius: "50%",
                background: "#FFE7A8",
                boxShadow: "0 0 26px #FFE7A8",
              }}
            />
            <div
              style={{
                position: "absolute",
                left: -30,
                bottom: -52,
                width: 230,
                height: 130,
                borderRadius: "50%",
                background: "#0B1338",
              }}
            />
            <div
              style={{
                position: "absolute",
                right: -40,
                bottom: -60,
                width: 260,
                height: 150,
                borderRadius: "50%",
                background: "#141B4D",
              }}
            />
            <div
              style={{
                position: "absolute",
                left: 26,
                bottom: 34,
                width: 46,
                height: 4,
                borderRadius: 4,
                background: "#FFFFFF40",
              }}
            />
            <div
              style={{
                position: "absolute",
                left: 26,
                bottom: 22,
                width: 76,
                height: 4,
                borderRadius: 4,
                background: "#FFFFFF66",
              }}
            />
          </div>
        </div>

        {/* ---------- 底部标题 ---------- */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: 505,
            textAlign: "center",
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
          }}
        >
          <div
            style={{
              fontSize: 42,
              fontWeight: 700,
              letterSpacing: 2,
              color: "#DCE3FF",
              textShadow: "0 0 30px #4E6BFF66",
            }}
          >
            MTNode{" "}
            <span style={{ color: "#6D6BFF" }}>·</span>{" "}
            <span style={{ color: "#C084FC" }}>连线即生产力</span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

